use super::*;
use crate::fiscal_repository::{Repository,Policy,Clock,ActivationIntent};
use crate::storage::{StorageService,PreferencePatch};
use nomina_fiscal_package::wire::Capability;
use std::{fs,path::{Path,PathBuf}};
fn id()->String{uuid::Uuid::new_v4().to_string()}
fn fixture(n:&str)->Vec<u8>{fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b2/fixtures").join(n)).unwrap()}
struct Qa{root:PathBuf,service:Arc<ExecutionService>,salary:Arc<StorageService>,owner:Owner,time:Arc<Mutex<String>>}
impl Qa{
 fn new(consent:bool)->Self{let root=std::env::temp_dir().join("opencode").join(format!("5b7-5d3b2-4d-{}",id()));let time=Arc::new(Mutex::new("2026-10-29T12:00:00Z".into()));let repo=Repository::new(root.clone(),Policy::import_qa()).execution_test_clock(Clock{fixed:Some(time.clone())});repo.initialize_new().unwrap();repo.accept_trust_episode(&id(),0,&[fixture("trust.json")]).unwrap();let iid=repo.record_verified_installation(&id(),1,&fixture("package1.nomina-fiscal"),&[Capability::Direct,Capability::Inverse]).unwrap().installation_id.unwrap();let p=repo.prepare_activation(ActivationIntent::Admit,Some(&iid),None,None).unwrap();repo.confirm_activation(&id(),&p).unwrap();let p=repo.prepare_activation(ActivationIntent::Select,Some(&iid),p.admission_id.as_deref(),None).unwrap();repo.confirm_activation(&id(),&p).unwrap();let salary=Arc::new(StorageService::new(Ok(root.clone())));salary.set_preferences(PreferencePatch{theme:None,history_auto_save:Some(consent)}).unwrap();let imports=Arc::new(ImportService::new(repo,true));let owner=imports.owner("main",900).unwrap();Self{root,service:Arc::new(ExecutionService::with_storage(imports,salary.clone())),salary,owner,time}}
 fn request(&self)->PrepareRequest{let selected=self.service.imports.repository.selection_status().unwrap().selection;let originals:Vec<serde_json::Value>=serde_json::from_str(include_str!("../../../docs/evidence/5d2b/originals-v2.json")).unwrap();let old:serde_json::Value=serde_json::from_str(originals[0]["payload"].as_str().unwrap()).unwrap();PrepareRequest{client_request_id:id(),request_id:1,expected_selection_id:selected.id.unwrap(),expected_selection_generation:selected.generation,capture:serde_json::from_value(old["value"]["capture"].clone()).unwrap(),scenario:old["value"]["executionProvenance"]["requestScenario"].clone()}}
 fn completed(&self)->State{let request=self.request();let state=self.service.prepare(&self.owner,&request).unwrap();assert_eq!(state.phase,"ready");let originals:Vec<serde_json::Value>=serde_json::from_str(include_str!("../../../docs/evidence/5d2b/originals-v2.json")).unwrap();let old:serde_json::Value=serde_json::from_str(originals[0]["payload"].as_str().unwrap()).unwrap();let wire=serde_json::json!({"capture":request.capture,"scenario":request.scenario,"contextSha256":state.context_sha256,"outcome":old["value"]["outcome"]}).to_string();self.service.complete(&self.owner,&CompleteRequest{handle:state.handle,result_wire:wire}).unwrap()}
 fn document(&self,s:&State)->(String,String,String){let d=self.service.finalize(&self.owner,&FinalizeRequest{handle:s.handle.clone(),expected_result_sha256:s.result_sha256.clone().unwrap()}).unwrap();(d.payload.clone(),d.checksum.clone(),d.write_generation.clone().unwrap_or_default())}
 fn store(&self,s:&State,p:&str,h:&str,g:&str,route:StoreRoute)->Result<StoreOutcome>{self.service.store_document(&self.owner,&AuthorityReference{handle:s.handle.clone(),expected_document_sha256:h.into()},g,p,route)}
 fn update(&self,n:&str){let r=&self.service.imports.repository;let g=r.open_existing().unwrap().generation;r.accept_trust_episode(&id(),g,&[fixture(n)]).unwrap();}
}
impl Drop for Qa{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
#[test]fn native_constructor_finalizes_existing_contract_without_claiming_storage(){let q=Qa::new(true);let s=q.completed();let(p,h,_)=q.document(&s);let v:serde_json::Value=serde_json::from_str(&p).unwrap();assert_eq!(v["value"]["documentKind"],"execution-record");assert_eq!(v["value"]["executionId"],s.execution_id);assert_eq!(v["value"]["executionProvenance"]["authorizationObservation"]["kind"],"native-observation-v1");assert_eq!(hashes::sha256(p.as_bytes()),h);assert_eq!(q.salary.list(10,None).unwrap().items.len(),0);}
#[test]fn both_native_salary_routes_store_a_genuine_finalization_and_preserve_exact_bytes(){for route in [StoreRoute::Manual,StoreRoute::Automatic]{let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);let stored=q.store(&s,&p,&h,&g,route).unwrap();assert_eq!(stored.status,"COMMITTED");assert_eq!(stored.stored,Some(true));assert_eq!(q.salary.get(&s.execution_id).unwrap().as_deref(),Some(p.as_str()));assert_eq!(q.store(&s,&p,&h,&g,route).unwrap().stored,Some(true));assert_eq!(q.salary.list(10,None).unwrap().items.len(),1);}}
#[test]fn complete_or_observation_json_is_not_a_write_permit(){let q=Qa::new(true);let s=q.completed();let doc=serde_json::from_slice::<serde_json::Value>(&fixture("package1.nomina-fiscal")).unwrap();assert_eq!(q.store(&s,&doc.to_string(),&"0".repeat(64),&q.salary.begin_write().unwrap().generation,StoreRoute::Manual).unwrap_err().code,"DOCUMENT_CONFLICT");let(p,_,g)=q.document(&s);assert_eq!(q.salary.insert(&g,&p).unwrap_err().code,"V3_WRITE_CLOSED");}
#[test]fn finalize_rejects_a_different_result_digest_and_an_unknown_uuid(){let q=Qa::new(true);let s=q.completed();assert_eq!(q.service.finalize(&q.owner,&FinalizeRequest{handle:s.handle.clone(),expected_result_sha256:"0".repeat(64)}).unwrap_err().code,"RESULT_CONFLICT");assert_eq!(q.service.finalize(&q.owner,&FinalizeRequest{handle:id(),expected_result_sha256:s.result_sha256.unwrap()}).unwrap_err().code,"SESSION_UNKNOWN");}
#[test]fn document_changes_and_fabricated_authorization_observations_are_rejected(){let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);let mut v:serde_json::Value=serde_json::from_str(&p).unwrap();v["value"]["executionProvenance"]["authorizationObservation"]["nativeExecutionId"]=id().into();let altered=v.to_string();assert_eq!(q.store(&s,&altered,&h,&g,StoreRoute::Manual).unwrap_err().code,"DOCUMENT_CONFLICT");assert_eq!(q.store(&s,&altered,&hashes::sha256(altered.as_bytes()),&g,StoreRoute::Manual).unwrap_err().code,"DOCUMENT_CONFLICT");}
#[test]fn later_consent_does_not_authorize_an_initially_ineligible_execution(){for route in [StoreRoute::Manual,StoreRoute::Automatic]{let q=Qa::new(false);let s=q.completed();q.salary.set_preferences(PreferencePatch{theme:None,history_auto_save:Some(true)}).unwrap();let(p,h,g)=q.document(&s);assert_eq!(q.store(&s,&p,&h,&g,route).unwrap_err().code,"INITIAL_CONSENT_REQUIRED");assert_eq!(q.salary.list(10,None).unwrap().items.len(),0);}}
#[test]fn opt_out_clear_and_tombstones_fence_old_authority(){for action in ["optout","clear","delete"]{let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);match action{"optout"=>{q.salary.set_preferences(PreferencePatch{theme:None,history_auto_save:Some(false)}).unwrap();},"clear"=>{q.salary.clear().unwrap();},_=>{q.salary.delete(&s.execution_id).unwrap();}}let e=q.store(&s,&p,&h,&g,StoreRoute::Automatic).unwrap_err();assert_eq!(e.code,if action=="delete"{"DELETED_EXECUTION"}else{"STALE_GENERATION"});}}
#[test]fn cancellation_and_expiry_before_store_do_not_persist(){for expired in [false,true]{let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);if expired{q.service.age(&s.handle,Duration::from_secs(600),Duration::ZERO);}else{q.service.cancel(&q.owner,&ReferenceRequest{handle:Some(s.handle.clone()),client_request_id:None}).unwrap();}assert!(q.store(&s,&p,&h,&g,StoreRoute::Manual).is_err());assert_eq!(q.salary.list(10,None).unwrap().items.len(),0);}}
#[test]fn revocation_or_expiry_before_store_blocks_and_keeps_history_unchanged(){for revoke in [true,false]{let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);if revoke{q.update("trust-revoked.json");}else{*q.time.lock().unwrap()="2027-01-01T00:00:00Z".into();}assert!(q.store(&s,&p,&h,&g,StoreRoute::Manual).is_err());assert_eq!(q.salary.list(10,None).unwrap().items.len(),0);}}
#[test]fn revocation_after_commit_never_rewrites_an_original(){let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);q.store(&s,&p,&h,&g,StoreRoute::Manual).unwrap();q.update("trust-revoked.json");assert_eq!(q.salary.get(&s.execution_id).unwrap().as_deref(),Some(p.as_str()));assert_eq!(q.salary.reconcile_v3(&s.execution_id,&h).unwrap().stored,Some(true));}
#[test]fn cancellation_after_commit_reports_the_existing_commit_instead_of_rollback(){let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);q.store(&s,&p,&h,&g,StoreRoute::Manual).unwrap();let result=q.service.cancel(&q.owner,&ReferenceRequest{handle:Some(s.handle.clone()),client_request_id:None}).unwrap();assert_eq!(result.phase,"stored");assert_eq!(q.salary.get(&s.execution_id).unwrap().as_deref(),Some(p.as_str()));}
#[test]fn restart_reconciles_only_existing_rows_and_never_resurrects_ram(){let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);q.store(&s,&p,&h,&g,StoreRoute::Automatic).unwrap();let reopened=StorageService::new(Ok(q.root.clone()));assert_eq!(reopened.reconcile_v3(&s.execution_id,&h).unwrap().stored,Some(true));assert_eq!(reopened.reconcile_v3(&id(),&h).unwrap().stored,Some(false));reopened.delete(&s.execution_id).unwrap();assert_eq!(reopened.reconcile_v3(&s.execution_id,&h).unwrap().reason.as_deref(),Some("DELETED_EXECUTION"));}
#[test]fn reconciliation_rejects_corrupted_checksum_salary_index_and_package_metadata(){for sql in ["UPDATE simulations SET payload_sha256=lower(hex(zeroblob(32)))","UPDATE simulations SET net='1.00'","UPDATE fiscal_packages SET version='forged'"]{let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);q.store(&s,&p,&h,&g,StoreRoute::Manual).unwrap();let c=rusqlite::Connection::open(q.root.join("payroll.sqlite3")).unwrap();c.execute_batch(sql).unwrap();drop(c);assert_eq!(q.salary.reconcile_v3(&s.execution_id,&h).unwrap_err().code,"CORRUPT_RECORD");}}
