#[test]fn committed_verification_pending_is_reconciled_without_a_second_insert(){let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);StorageService::v3_test_fault(Some("salary-before-verification"));let unknown=q.store(&s,&p,&h,&g,StoreRoute::Automatic).unwrap();assert_eq!(unknown.status,"COMMITTED_VERIFICATION_PENDING");assert_eq!(unknown.stored,None);StorageService::v3_test_fault(None);assert_eq!(q.store(&s,&p,&h,&g,StoreRoute::Automatic).unwrap().stored,Some(true));assert_eq!(q.salary.list(10,None).unwrap().items.len(),1);}
#[test]fn finalization_and_store_preserve_the_process_maximum_utc(){let q=Qa::new(true);let s=q.completed();*q.time.lock().unwrap()="2026-10-29T12:10:00Z".into();let(p,h,g)=q.document(&s);*q.time.lock().unwrap()="2026-10-29T12:05:00Z".into();assert_eq!(q.service.finalize(&q.owner,&FinalizeRequest{handle:s.handle.clone(),expected_result_sha256:s.result_sha256.clone().unwrap()}).unwrap_err().code,"CLOCK_ROLLBACK");assert_eq!(q.store(&s,&p,&h,&g,StoreRoute::Manual).unwrap_err().code,"CLOCK_ROLLBACK");assert_eq!(q.salary.get(&s.execution_id).unwrap(),None);*q.time.lock().unwrap()="2026-10-29T12:11:00Z".into();q.store(&s,&p,&h,&g,StoreRoute::Manual).unwrap();assert_eq!(q.service.registry.lock().unwrap().maximum_utc,"2026-10-29T12:11:00Z");}
#[test]fn missing_salary_database_is_unknown_not_a_new_empty_history(){let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);q.store(&s,&p,&h,&g,StoreRoute::Manual).unwrap();for suffix in ["","-wal","-shm"]{let path=q.root.join(format!("payroll.sqlite3{suffix}"));if path.exists(){fs::remove_file(path).unwrap();}}let result=q.salary.reconcile_v3(&s.execution_id,&h).unwrap();assert_eq!(result.status,"OUTCOME_UNKNOWN");assert!(!q.root.join("payroll.sqlite3").exists());}
#[test]fn native_document_budget_accepts_valid_n_and_rejects_n_plus_one_without_truncation(){let q=Qa::new(true);let base=q.completed();let(p,_,_)=q.document(&base);let delta=RESULT_MAX-p.len();q.service.cancel(&q.owner,&ReferenceRequest{handle:Some(base.handle),client_request_id:None}).unwrap();let originals:Vec<serde_json::Value>=serde_json::from_str(include_str!("../../../docs/evidence/5d2b/originals-v2.json")).unwrap();let original:serde_json::Value=serde_json::from_str(originals[0]["payload"].as_str().unwrap()).unwrap();for extra in [0,1]{let r=q.request();let ready=q.service.prepare(&q.owner,&r).unwrap();let mut outcome=original["value"]["outcome"].clone();let old=outcome["report"]["provenance"]["assumptions"][0].as_str().unwrap().to_owned();outcome["report"]["provenance"]["assumptions"][0]=format!("{old}{}","Q".repeat(delta+extra)).into();let wire=serde_json::json!({"capture":r.capture,"scenario":r.scenario,"contextSha256":ready.context_sha256,"outcome":outcome}).to_string();let done=q.service.complete(&q.owner,&CompleteRequest{handle:ready.handle,result_wire:wire}).unwrap();let finalization=q.service.finalize(&q.owner,&FinalizeRequest{handle:done.handle.clone(),expected_result_sha256:done.result_sha256.unwrap()});if extra==0{let d=finalization.unwrap();assert_eq!(d.payload.len(),RESULT_MAX);}else{assert_eq!(finalization.unwrap_err().code,"DOCUMENT_TOO_LARGE");}q.service.cancel(&q.owner,&ReferenceRequest{handle:Some(done.handle),client_request_id:None}).unwrap();}fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b4d/budget.json"),serde_json::to_vec_pretty(&serde_json::json!({"validDocumentBytes":RESULT_MAX,"nextDocumentBytes":RESULT_MAX+1,"nAccepted":true,"nextRejected":true,"outcomePaddedBeforeComplete":true,"financialAmountsUnchanged":true,"level":"native module controlled QA outcome; not GUI engine proof"})).unwrap()).unwrap();}
#[test]fn cancelled_or_foreign_owner_cannot_finalize_or_store(){let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);let mut foreign=q.owner.clone();foreign.incarnation=id();assert_eq!(q.service.store_document(&foreign,&AuthorityReference{handle:s.handle.clone(),expected_document_sha256:h.clone()},&g,&p,StoreRoute::Manual).unwrap_err().code,"SESSION_OWNER_MISMATCH");q.service.cancel(&q.owner,&ReferenceRequest{handle:Some(s.handle.clone()),client_request_id:None}).unwrap();assert!(q.service.finalize(&q.owner,&FinalizeRequest{handle:s.handle,expected_result_sha256:s.result_sha256.unwrap()}).is_err());}
#[test]fn finalization_transfer_respects_global_reservations_and_raii_release(){
 let q=Qa::new(true);let base=q.completed();let(payload,_,_)=q.document(&base);let padding=RESULT_MAX-payload.len();q.service.cancel(&q.owner,&ReferenceRequest{handle:Some(base.handle),client_request_id:None}).unwrap();
 let originals:Vec<serde_json::Value>=serde_json::from_str(include_str!("../../../docs/evidence/5d2b/originals-v2.json")).unwrap();let old:serde_json::Value=serde_json::from_str(originals[0]["payload"].as_str().unwrap()).unwrap();let mut outcome=old["value"]["outcome"].clone();let assumption=outcome["report"]["provenance"]["assumptions"][0].as_str().unwrap().to_owned();outcome["report"]["provenance"]["assumptions"][0]=format!("{assumption}{}","Q".repeat(padding)).into();
 // Like the preceding 4-C quota test: retain old owner reservations, then issue
 // two sessions for a changed native handle. This is not four GUI windows.
 let mut other=None;let mut sessions=vec![];for index in 0..4{let owner=if index<2{q.owner.clone()}else{other.get_or_insert_with(||q.service.imports.owner("main",901).unwrap()).clone()};let r=q.request();let ready=q.service.prepare(&owner,&r).unwrap();let done=q.service.complete(&owner,&CompleteRequest{handle:ready.handle,result_wire:serde_json::json!({"capture":r.capture,"scenario":r.scenario,"contextSha256":ready.context_sha256,"outcome":outcome}).to_string()}).unwrap();sessions.push((owner,done));}
 let(owner,s)=&sessions[3];let request=FinalizeRequest{handle:s.handle.clone(),expected_result_sha256:s.result_sha256.clone().unwrap()};assert_eq!(q.service.finalize(owner,&request).unwrap_err().code,"EXECUTION_CAPACITY");let(release_owner,release)=&sessions[2];q.service.cancel(release_owner,&ReferenceRequest{handle:Some(release.handle.clone()),client_request_id:None}).unwrap();
 let d=q.service.finalize(owner,&request).unwrap();let(retained,transfer,peak)=q.service.budget_metrics();let wire=serde_json::to_vec(&d).unwrap();assert_eq!(d.payload.len(),RESULT_MAX);assert!(wire.len()<=transfer&&retained+transfer<=RETAINED_MAX&&peak<=RETAINED_MAX);assert_eq!(q.service.finalize(owner,&request).unwrap_err().code,"MATERIAL_TRANSFER_BUSY");drop(d);assert_eq!(q.service.budget_metrics().1,0);
 fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b4d/global-budget.json"),serde_json::to_vec_pretty(&serde_json::json!({"limit":RETAINED_MAX,"retainedReservations":retained,"transferReservation":transfer,"actualEncodedResponseBytes":wire.len(),"peakEncodedBudget":peak,"fourthSessionBlocksMaxDocumentTransfer":true,"retryAfterRelease":true,"raiiReleasesTransfer":true,"heapTotalMeasured":false,"notFourGuiWindows":true})).unwrap()).unwrap();
}
#[test]fn actual_process_kills_at_salary_commit_points_keep_atomic_originals(){use std::io::BufRead;let mut results=vec![];for point in ["salary-before-commit","salary-after-commit","salary-before-response"]{let mut process=std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","fiscal_execution::service::finalization::tests::persistence_child","--ignored","--nocapture"]).env("NOMINA_4D_STOP",point).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::piped()).spawn().unwrap();let mut metadata=None;let mut seen=false;for line in std::io::BufReader::new(process.stdout.take().unwrap()).lines(){let line=line.unwrap();if let Some(json)=line.strip_prefix("SALARY_4D_CONTEXT:"){metadata=Some(serde_json::from_str::<serde_json::Value>(json).unwrap());}if line.contains(&format!("SALARY_4D_READY:{point}")){seen=true;break;}}assert!(seen);let info=metadata.unwrap();process.kill().unwrap();process.wait().unwrap();let path=PathBuf::from(info["root"].as_str().unwrap());assert!(path.starts_with(std::env::temp_dir().join("opencode")));let salary=StorageService::new(Ok(path.clone()));let observed=salary.reconcile_v3(info["executionId"].as_str().unwrap(),info["checksum"].as_str().unwrap()).unwrap();let committed=point!="salary-before-commit";assert_eq!(observed.stored,Some(committed));if committed{let bytes=salary.get(info["executionId"].as_str().unwrap()).unwrap().unwrap();assert_eq!(hashes::sha256(bytes.as_bytes()),info["checksum"]);}results.push(serde_json::json!({"point":point,"externallyTerminated":true,"committed":committed,"reconciled":observed.status,"schema":4}));fs::remove_dir_all(path).unwrap();}fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b4d/process-crashes.json"),serde_json::to_vec_pretty(&results).unwrap()).unwrap();}
#[test]#[ignore="Native subprocess helper exercised at three salary commit boundaries"]fn persistence_child(){let q=Qa::new(true);let s=q.completed();let(p,h,g)=q.document(&s);println!("SALARY_4D_CONTEXT:{}",serde_json::json!({"root":q.root,"executionId":s.execution_id,"checksum":h}));use std::io::Write;std::io::stdout().flush().unwrap();if std::env::var_os("NOMINA_4D_ORDERING").is_some(){unsafe{std::env::set_var("NOMINA_4D_RELEASE_FILE",q.root.join("release-writer"));}}q.store(&s,&p,&h,&g,StoreRoute::Automatic).unwrap();println!("SALARY_4D_COMMITTED");std::io::stdout().flush().unwrap();loop{std::thread::park();}}
